import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import {NativeHomeSession} from '../session.mjs';
const root=new URL('../',import.meta.url),c=JSON.parse(fs.readFileSync(new URL('contract.json',root))),travel=JSON.parse(fs.readFileSync(new URL('travel-routes.json',root))),masks=Object.fromEntries(Object.entries(c.masks).map(([k,s])=>[k,new Uint8Array(fs.readFileSync(new URL(s.path,root)))]));
const make=(homeId='upper',extra={})=>new NativeHomeSession({contract:c,homeId,masks,...extra});
function walk(s,path){assert.deepEqual(s.foot,path[0]);for(const p of path.slice(1)){const[x,y]=s.foot;assert.equal(Math.abs(x-p[0])+Math.abs(y-p[1]),1);assert.equal(s.move(p[0]<x?'left':p[0]>x?'right':p[1]<y?'up':'down').ok,true)}}
function exit(s){const path=c.floors[s.scene].routes.entryArrival_entry;walk(s,path);s.face('down');return s.action()}
for(const from of ['upper','family','coastal'])for(const to of ['upper','family','coastal'])test(`shared session ${from} -> ${to} through unchanged support and exact room`,async()=>{const s=make(from);s.setDoorState('OPEN',to);walk(s,travel.routes[from+'__'+to]);s.face('up');assert.equal(s.snapshot().doorAtFoot,to);assert.equal((await s.action()).kind,'enter');assert.equal(s.homeId,to);assert.equal(s.scene,c.houses[to].firstFloor);s.releaseAction();assert.equal((await exit(s)).kind,'return');assert.deepEqual(s.foot,c.houses[to].exteriorDoor.arrival);assert.equal(s.portalTransfers,2)});
test('one session upper -> family -> coastal -> upper, separate door states and accumulated receipts',async()=>{const s=make();s.setDoorState('OPEN','upper');for(const [from,to]of [['upper','family'],['family','coastal'],['coastal','upper']]){walk(s,travel.routes[from+'__'+to]);s.face('up');if(to!=='upper'){assert.equal((await s.action()).reason,'DOOR_CLOSED');s.releaseAction();s.setDoorState('OPEN',to)}assert.equal((await s.action()).kind,'enter');s.releaseAction();assert.equal((await exit(s)).kind,'return');s.releaseAction()}assert.equal(s.portalTransfers,6);assert.equal(s.receipts.length,6);assert.deepEqual(s.doorStates,{upper:'OPEN',family:'OPEN',coastal:'OPEN'})});
test('failed different-home target cannot mutate active home; new door permission invalidates async',async()=>{let resolve;const s=make('upper',{loadScene:()=>new Promise(r=>resolve=r)});s.setDoorState('OPEN','family');walk(s,travel.routes.upper__family);s.face('up');const p=s.action();s.setDoorState('CLOSED','family');resolve({sha256:c.sources.family_1F.sha256});assert.equal((await p).reason,'STALE');assert.equal(s.homeId,'upper');assert.equal(s.scene,'exterior')});
test('new target unsupported cannot steal active home',async()=>{const s=make();s.masks.family_1F.fill(0);s.setDoorState('OPEN','family');walk(s,travel.routes.upper__family);s.face('up');assert.equal((await s.action()).reason,'TARGET_FOOT_UNSUPPORTED');assert.equal(s.homeId,'upper');assert.equal(s.h.firstFloor,'upper_1F')});
for(const direction of ['up','down','left','right'])test(`gait ${direction} derives actual distance and goes idle on face/stop`,()=>{const s=make();s.foot=[3280, 600];assert(s.safe('exterior',s.foot));s.face(direction);const base={down:0,right:3,left:6,up:9}[direction];assert.equal(s.pose(),base);for(let n=1;n<=24;n++){assert(s.move(direction).ok);assert.equal(s.pose(),base+1+(Math.floor(n/12)%2));assert.equal(s.gaitDistance,n)}s.stopGait();assert.equal(s.pose(),base);s.face(direction);assert.equal(s.pose(),base)});
test('blocked movement/invalid controls do not accumulate distance; reset invalidates all door states',()=>{const s=make();s.foot=[0,0];assert(!s.move('left').ok);assert.equal(s.gaitDistance,0);assert(!s.moving);assert.equal(s.setDoorState('OPEN','unknown').reason,'UNREGISTERED_HOME');s.setDoorState('OPEN','family');s.reset();assert.deepEqual(s.doorStates,{upper:'CLOSED',family:'CLOSED',coastal:'CLOSED'});assert.equal(s.pose(),9)});
